-- Replace "Did you know" content wholesale with the
-- DidYouKnow_PRODUCTION_v4 workbook (1032 cards, Cards sheet).
--
-- Two real changes from the v1 workbook this table was built from:
--   1. No "Header" column exists anymore -- the per-card heading
--      ("Sound familiar?", "Through their eyes", etc.) is gone from the
--      source data entirely, not just unused. The column is dropped, not
--      just left nullable, since nothing will ever populate it again.
--      See components/DidYouKnowTile.tsx for the matching UI change.
--   2. Two new source-tracking columns exist (Card ID, Batch) -- kept as
--      nullable metadata columns even though the app doesn't read them,
--      in case a future content refresh needs to reference them.
--
-- age_min_months/age_max_months are parsed from the sheet's free-text
-- "Age Range" the same way the original migration did: "Prenatal" alone
-- is -9/0; "Prenatal-X" is -9/X; an "X yrs+" open upper bound is 9999;
-- a single age point ("12 mo") sets min=max to that same value. New this
-- round: a handful of rows give age in weeks ("1 wk", "6 wk") -- these
-- convert to months via weeks/4.345 (average weeks per month), rounded,
-- e.g. "6 wk" -> 1 month. is_research_based is true for Species = "Fact"
-- or "Research insight", same rule as before.
alter table did_you_know_facts drop column if exists header;
alter table did_you_know_facts add column if not exists card_id text;
alter table did_you_know_facts add column if not exists batch text;

truncate table did_you_know_facts;

insert into did_you_know_facts (
  id, card_id, card_text, india_variant_text, species, lane, theme, age_relevance,
  age_range_raw, age_min_months, age_max_months, geography, region, feeling, audience,
  evidence_level, source_citation, source_url, is_research_based, batch
)
